def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    def tenths(value: int, scale: int) -> int:
        return (20 * value + scale) // (2 * scale)

    for scale, suffix in ((1_000, "mil"), (1_000_000, "mi"), (1_000_000_000, "bi")):
        t = tenths(n, scale)
        if t < 10_000 or scale == 1_000_000_000:
            whole, frac = divmod(t, 10)
            return f"{whole},{frac} {suffix}" if frac else f"{whole} {suffix}"
