def reached(value, threshold) -> bool:
    from decimal import Decimal

    for x in (value, threshold):
        if isinstance(x, bool) or not isinstance(x, (int, float, Decimal)):
            raise TypeError("value and threshold must be int, float, or decimal.Decimal")

    def as_decimal(x):
        if isinstance(x, float):
            return Decimal(repr(x))
        if isinstance(x, int):
            return Decimal(x)
        return x

    return as_decimal(value) >= as_decimal(threshold)
```

