from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("empty currency string")

    negative = False

    if s.startswith('('):
        if not s.endswith(')'):
            raise ValueError("unmatched parenthesis")
        s = s[1:-1].strip()
        negative = True

    if s.startswith('-'):
        s = s[1:].strip()
        negative = True

        if s.startswith('('):
            if not s.endswith(')'):
                raise ValueError("unmatched parenthesis")
            s = s[1:-1].strip()

    if s.startswith('R$'):
        s = s[2:].strip()

    if not s:
        raise ValueError("missing amount")

    if ',' in s:
        integer_part, cents = s.split(',', 1)
        if len(cents) != 2 or not cents.isdigit():
            raise ValueError("cents must contain exactly two digits")
    else:
        integer_part = s
        cents = ""

    if not integer_part:
        raise ValueError("missing integer part")

    if '.' in integer_part:
        parts = integer_part.split('.')
        if len(parts) > 1:
            if not (1 <= len(parts[0]) <= 3):
                raise ValueError("invalid grouped integer part")
            for part in parts[1:]:
                if len(part) != 3 or not part.isdigit():
                    raise ValueError("grouped integer parts must contain exactly three digits")
            if not parts[0].isdigit():
                raise ValueError("invalid grouped integer part")
        else:
            raise ValueError("invalid grouped integer part")
    else:
        if not integer_part.isdigit():
            raise ValueError("integer part must contain digits only")

    value = Decimal(integer_part + ('.' + cents if cents else ''))
    if negative:
        value = -value

    return value
```

