def compare_versions(a: str, b: str) -> int:
    def parse(version: str):
        version = version.strip()
        core = version.split("+", 1)[0]

        if "-" in core:
            main_part, pre_part = core.split("-", 1)
        else:
            main_part, pre_part = core, ""

        main = tuple(int(x) for x in main_part.split(".")[:3])
        pre_ids = pre_part.split(".") if pre_part else []
        return main, pre_ids

    a_main, a_pre = parse(a)
    b_main, b_pre = parse(b)

    if a_main < b_main:
        return -1
    if a_main > b_main:
        return 1

    if a_pre and not b_pre:
        return -1
    if b_pre and not a_pre:
        return 1
    if not a_pre and not b_pre:
        return 0

    for a_id, b_id in zip(a_pre, b_pre):
        a_numeric = a_id.isdigit()
        b_numeric = b_id.isdigit()

        if a_numeric and b_numeric:
            if int(a_id) < int(b_id):
                return -1
            if int(a_id) > int(b_id):
                return 1
        elif a_numeric:
            return -1
        elif b_numeric:
            return 1
        else:
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1

    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1
    return 0
```

