def natural_sorted(names: list[str]) -> list[str]:
    def sort_key(name: str):
        tokens = []
        i = 0
        n = len(name)

        while i < n:
            if name[i].isdecimal():
                j = i + 1
                while j < n and name[j].isdecimal():
                    j += 1
                tokens.append((0, int(name[i:j])))
                i = j
            else:
                j = i + 1
                while j < n and not name[j].isdecimal():
                    j += 1
                tokens.append((1, name[i:j].casefold()))
                i = j

        return tuple(tokens)

    return sorted(names, key=sort_key)
```

