def sort_names(names: list[str]) -> list[str]:
    import unicodedata

    def remove_accents(value: str) -> str:
        decomposed = unicodedata.normalize("NFD", value)
        return "".join(ch for ch in decomposed if not unicodedata.combining(ch))

    def has_accents(value: str) -> bool:
        return any(unicodedata.combining(ch) for ch in unicodedata.normalize("NFD", value))

    def sort_key(name: str) -> tuple[str, bool, str]:
        return remove_accents(name).casefold(), has_accents(name), name

    return sorted(names, key=sort_key)
```

