def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words or width <= 0:
        return []

    lines: list[str] = []
    current: list[str] = []
    current_len = 0

    for word in words:
        if len(word) > width:
            if current:
                lines.append(" ".join(current))
                current = []
                current_len = 0

            for i in range(0, len(word), width):
                piece = word[i:i + width]
                if current:
                    lines.append(" ".join(current))
                    current = []
                    current_len = 0

                current.append(piece)
                current_len = len(piece)
        else:
            word_len = len(word)
            if current_len == 0:
                current.append(word)
                current_len = word_len
            elif current_len + 1 + word_len <= width:
                current.append(word)
                current_len += 1 + word_len
            else:
                lines.append(" ".join(current))
                current = [word]
                current_len = word_len

    if current:
        lines.append(" ".join(current))

    return lines
```

