def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    result = []
    in_section = False
    found = False

    for line in lines:
        if line.endswith("\r\n"):
            content, ending = line[:-2], "\r\n"
        elif line.endswith("\n"):
            content, ending = line[:-1], "\n"
        elif line.endswith("\r"):
            content, ending = line[:-1], "\r"
        else:
            content, ending = line, ""

        stripped = content.strip()

        if stripped.startswith(";") or stripped.startswith("#"):
            result.append(line)
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            in_section = stripped[1:-1].strip() == section
            result.append(line)
            continue

        if in_section and "=" in content:
            key_part = content.split("=", 1)[0].strip()
            if key_part == key:
                result.append(f"{key} = {value}{ending}")
                found = True
                continue

        result.append(line)

    if not in_section:
        raise KeyError(section)
    if not found:
        raise KeyError(key)

    return "".join(result)
```

