def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime, timezone

    def parse_iso8601(value: str) -> datetime:
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed

    result: list[dict] = []
    positions: dict = {}
    timestamps: dict = {}

    for record in records:
        value = record[key]
        timestamp = parse_iso8601(record["updated_at"])

        if value not in positions:
            positions[value] = len(result)
            timestamps[value] = timestamp
            result.append(record)
        elif timestamp >= timestamps[value]:
            result[positions[value]] = record
            timestamps[value] = timestamp

    return result
```

