import ipaddress


def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        ip_addr = ipaddress.ip_address(ip)
    except (ValueError, TypeError):
        return False

    if isinstance(ip_addr, ipaddress.IPv6Address) and ip_addr.ipv4_mapped is not None:
        ip_addr = ip_addr.ipv4_mapped

    for network in networks:
        try:
            net = ipaddress.ip_network(network, strict=False)
        except (ValueError, TypeError) as exc:
            raise ValueError(f"Invalid network: {network!r}") from exc

        if isinstance(net, ipaddress.IPv6Network) and net.network_address.ipv4_mapped is not None:
            prefix_len = net.prefixlen
            if prefix_len >= 96:
                net = ipaddress.IPv4Network(
                    f"{net.network_address.ipv4_mapped}/{prefix_len - 96}"
                )

        try:
            if ip_addr in net:
                return True
        except TypeError:
            continue

    return False
