def minPath(grid, k):
    n = len(grid)

    start_r, start_c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_r, start_c = i, j
                break
        else:
            continue
        break

    path = [1]
    r, c = start_r, start_c
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for _ in range(k - 1):
        best_value = None
        best_r, best_c = r, c

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                value = grid[nr][nc]
                if best_value is None or value < best_value:
                    best_value = value
                    best_r, best_c = nr, nc

        path.append(best_value)
        r, c = best_r, best_c

    return path
