def is_woodall(num):
    if not isinstance(num, int) or num < 1:
        return False

    target = num + 1
    low, high = 1, target.bit_length()

    while low <= high:
        mid = (low + high) // 2
        value = mid * (1 << mid) - 1

        if value == num:
            return True
        if value < num:
            low = mid + 1
        else:
            high = mid - 1

