def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    scales = [(10**3, "mil"), (10**6, "mi"), (10**9, "bi")]

    for i, (scale, unit) in enumerate(scales):
        if n >= scale:
            tenths = (20 * n + scale) // (2 * scale)

            if tenths >= 10000 and i + 1 < len(scales):
                continue

            integer = tenths // 10
            decimal = tenths % 10
            return f"{integer},{decimal} {unit}" if decimal else f"{integer} {unit}"

    scale, unit = scales[-1]
    tenths = (20 * n + scale) // (2 * scale)
    integer = tenths // 10
    decimal = tenths % 10
    return f"{integer},{decimal} {unit}" if decimal else f"{integer} {unit}"
