def reached(value, threshold) -> bool:
    from decimal import Decimal

    if isinstance(value, bool) or isinstance(threshold, bool):
        raise TypeError("value and threshold must be int, float, or Decimal")

    if not isinstance(value, (int, float, Decimal)) or not isinstance(threshold, (int, float, Decimal)):
        raise TypeError("value and threshold must be int, float, or Decimal")

    if isinstance(value, float):
        value_decimal = Decimal(str(value))
    elif isinstance(value, int):
        value_decimal = Decimal(value)
    else:
        value_decimal = value

    if isinstance(threshold, float):
        threshold_decimal = Decimal(str(threshold))
    elif isinstance(threshold, int):
        threshold_decimal = Decimal(threshold)
    else:
