def compare_versions(a: str, b: str) -> int:
    def parse(version: str):
        version = version.strip()

        if "+" in version:
            version = version.split("+", 1)[0]

        if "-" in version:
            core, pre_release = version.split("-", 1)
        else:
            core, pre_release = version, None

        parts = core.split(".")
        while len(parts) < 3:
            parts.append("0")
        major, minor, patch = (int(parts[0]), int(parts[1]), int(parts[2]))

        if pre_release is None:
            prerelease_ids = None
        else:
            prerelease_ids = pre_release.split(".")

        return major, minor, patch, prerelease_ids

    def compare_prerelease(left, right) -> int:
        if left is None and right is None:
            return 0
        if left is None:
            return 1
        if right is None:
            return -1

        for l, r in zip(left, right):
            l_numeric = bool(l) and all(c in "0123456789" for c in l)
            r_numeric = bool(r) and all(c in "0123456789" for c in r)

            if l_numeric and r_numeric:
                lv, rv = int(l), int(r)
                if lv < rv:
                    return -1
                if lv > rv:
                    return 1
            elif l_numeric:
                return -1
            elif r_numeric:
                return 1
            else:
                if l < r:
                    return -1
                if l > r:
                    return 1

        if len(left) < len(right):
            return -1
        if len(left) > len(right):
            return 1
        return 0

    a_major, a_minor, a_patch, a_pre = parse(a)
    b_major, b_minor, b_patch, b_pre = parse(b)

    for a_part, b_part in ((a_major, b_major), (a_minor, b_minor), (a_patch, b_patch)):
        if a_part < b_part:
            return -1
        if a_part > b_part:
            return 1

    return compare_prerelease(a_pre, b_pre)
