def build_order(deps: dict[str, list[str]]) -> list[str]:
    import heapq

    all_items = set(deps)
    for dependencies in deps.values():
        all_items.update(dependencies)

    dependents = {item: [] for item in all_items}
    indegree = {item: 0 for item in all_items}

    for item, dependencies in deps.items():
        for dependency in set(dependencies):
            dependents[dependency].append(item)
            indegree[item] += 1

    ready = [item for item in all_items if indegree[item] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        item = heapq.heappop(ready)
        order.append(item)

        for dependent in dependents[item]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(all_items):
        raise ValueError("Dependency graph contains a cycle")

    return order
```

