import re


def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = re.findall(r"(?:.*?)(?:\r\n|\n|\r|$)", text, flags=re.DOTALL)
    target_line = -1
    in_target_section = False

    for i, line in enumerate(lines):
        stripped = line.strip()

        if stripped.startswith((";", "#")) or not stripped:
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            name = stripped[1:-1].strip()
            in_target_section = name == section
            continue

        if not in_target_section or "=" not in stripped:
            continue

        parsed_key = stripped.split("=", 1)[0].strip()
        if parsed_key == key:
            target_line = i
            break

    if target_line == -1:
        raise KeyError

    original = lines[target_line]
    if original.endswith("\r\n"):
        ending = "\r\n"
    elif original.endswith("\n"):
        ending = "\n"
    elif original.endswith("\r"):
        ending = "\r"
    else:
        ending = ""

    lines[target_line] = f"{key} = {value}{ending}"
    return "".join(lines)
