def parse_duration(s: str) -> int:
    import re

    if not isinstance(s, str) or not s.strip():
        raise ValueError("invalid duration")

    match = re.fullmatch(r"(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?", s.strip())
