def compact(n: int) -> str:
    def round_tenths(value: int, scale: int) -> int:
        tenths = value * 10
        q, r = divmod(tenths, scale)
        if r * 2 >= scale:
            q += 1
        return q

    def fmt(tenths: int, unit: str) -> str:
        whole, frac = divmod(tenths, 10)
        number = str(whole) if frac == 0 else f"{whole},{frac}"
        return f"{number} {unit}"

    if n < 1000:
        return str(n)

    if n >= 1_000_000_000 or round_tenths(n, 1_000_000) >= 10_000:
        return fmt(round_tenths(n, 1_000_000_000), "bi")

    if n >= 1_000_000 or round_tenths(n, 1_000) >= 10_000:
        return fmt(round_tenths(n, 1_000_000), "mi")

    return fmt(round_tenths(n, 1_000), "mil")
