def compare_versions(a: str, b: str) -> int:
    def is_numeric(identifier: str) -> bool:
        return len(identifier) > 0 and all(ch in "0123456789" for ch in identifier)

    def parse(version: str):
        version = version.strip().split("+", 1)[0]

        if "-" in version:
            core, prerelease = version.split("-", 1)
        else:
            core, prerelease = version, None

        major, minor, patch = core.split(".")
        core_version = (int(major), int(minor), int(patch))

        if prerelease is None:
            return (core_version, 1, [])

        identifiers = prerelease.split(".")
        prerelease_key = []
        for identifier in identifiers:
            if is_numeric(identifier):
                prerelease_key.append((0, int(identifier), ""))
            else:
                prerelease_key.append((1, 0, identifier))

        return (core_version, 0, prerelease_key)

    key_a = parse(a)
    key_b = parse(b)

    if key_a < key_b:
        return -1
    if key_a > key_b:
        return 1
    return 0
```

