def build_order(deps: dict[str, list[str]]) -> list[str]:
    import heapq

    nodes = set(deps)
    for item_dependencies in deps.values():
        nodes.update(item_dependencies)

    dependents = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}

    for item, item_dependencies in deps.items():
        for dependency in set(item_dependencies):
            if item not in dependents[dependency]:
                dependents[dependency].add(item)
                indegree[item] += 1

    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        item = heapq.heappop(ready)
        order.append(item)

        for dependent in dependents[item]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order
```

