def natural_sorted(names: list[str]) -> list[str]:
    import re

    def key(name: str) -> tuple:
        parts = []
        for part in re.findall(r"\d+|\D+", name):
            if part.isdigit():
                parts.append((0, int(part)))
            else:
                parts.append((1, part.casefold()))
        return tuple(parts)

    return sorted(names, key=key)
