def wrap(text: str, width: int) -> list[str]:
    if width <= 0:
        return []

    tokens: list[str] = []
    for word in text.split():
        if len(word) > width:
            for i in range(0, len(word), width):
                tokens.append(word[i:i + width])
        else:
            tokens.append(word)

    if not tokens:
        return []

    lines: list[str] = []
    current: list[str] = []
    current_len = 0

    for token in tokens:
        token_len = len(token)
        if not current:
            current = [token]
            current_len = token_len
        elif current_len + 1 + token_len <= width:
            current.append(token)
            current_len += 1 + token_len
        else:
            lines.append(" ".join(current))
            current = [token]
            current_len = token_len

    if current:
        lines.append(" ".join(current))

    return lines
```

