def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    in_section = False

    for i, line in enumerate(lines):
        stripped_end = line.rstrip("\r\n")
        line_end = line[len(stripped_end):]
        stripped = stripped_end.strip()

        if not stripped or stripped[0] in ";#":
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            in_section = stripped[1:-1].strip() == section
            continue

        if in_section and "=" in stripped_end:
            key_part = stripped_end.split("=", 1)[0].strip()
            if key_part == key:
                lines[i] = f"{key} = {value}{line_end}"
                return "".join(lines)

    raise KeyError
