def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime, timezone

    latest: dict = {}

    for record in records:
        value = record[key]

        ts = record["updated_at"].strip()
        if ts.endswith(("Z", "z")):
            ts = ts[:-1] + "+00:00"

        parsed = datetime.fromisoformat(ts)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)

        if value not in latest or parsed >= latest[value][0]:
            latest[value] = (parsed, record)

    return [record for _, record in latest.values()]
