def ip_allowed(ip: str, networks: list[str]) -> bool:
    from ipaddress import ip_address, ip_network

    parsed_networks = []
    for network in networks:
        try:
            if not isinstance(network, str):
                raise ValueError
            parsed_networks.append(ip_network(network, strict=False))
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError(f"Invalid network: {network!r}") from exc

    try:
        address = ip_address(ip)
    except (ValueError, TypeError):
        return False

    if isinstance(address, ipaddress.IPv6Address if (ipaddress := __import__("ipaddress")) else object) and address.ipv4_mapped is not None:
        address = address.ipv4_mapped

    for network in parsed_networks:
        if address.version == network.version and address in network:
            return True

    return False
